import{_ as s,o as t,c as i,a5 as e}from"./chunks/framework.BmD0ICqc.js";const n="/study/images/game/save-data-and-serialization.svg",g=JSON.parse('{"title":"セーブとシリアライズの基本 — 実行中の状態を保存する","description":"","frontmatter":{"title":"セーブとシリアライズの基本 — 実行中の状態を保存する","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"game","summary":"実行中のHPや進行状況から保存用のデータを選び、形式へ変換してファイルに保存し、読み戻して検証・復元する流れを説明する。","aliases":["セーブ","save","ロード","保存データ","シリアライズ","serialize","デシリアライズ","JSON","バージョン","マイグレーション","スナップショット"],"verification":"MicrosoftのJSONシリアライズ、Unityの保存先とWindowsのファイル書き込みの公式資料に照合（2026-11-07）"}},"headers":[],"relativePath":"game/basics/save-data-and-serialization.md","filePath":"game/basics/save-data-and-serialization.md"}'),r={name:"game/basics/save-data-and-serialization.md"};function o(l,a,h,d,p,k){return t(),i("div",null,[...a[0]||(a[0]=[e('<h1 id="セーブとシリアライズの基本-—-実行中の状態を保存する" tabindex="-1">セーブとシリアライズの基本 — 実行中の状態を保存する <a class="header-anchor" href="#セーブとシリアライズの基本-—-実行中の状態を保存する" aria-label="Permalink to &quot;セーブとシリアライズの基本 — 実行中の状態を保存する&quot;">​</a></h1><p>ゲームを終了して次に起動したとき、プレイヤーの進行状況を続きから使いたいことがあります。実行中のデータから必要なものを選び、保存できる形にして残すのが<strong>セーブ</strong>です。読み戻すときは、保存した値をゲームの状態へ復元します。<a href="/study/game/basics/game-engine-basics.html">ゲームエンジンと実行中の状態</a></p><h2 id="素材、設定、進行状況を見分ける" tabindex="-1">素材、設定、進行状況を見分ける <a class="header-anchor" href="#素材、設定、進行状況を見分ける" aria-label="Permalink to &quot;素材、設定、進行状況を見分ける&quot;">​</a></h2><table tabindex="0"><thead><tr><th>データ</th><th>例</th><th>扱い方の例</th></tr></thead><tbody><tr><td><strong>アセット</strong></td><td>敵のモデル、アイテムの定義、ステージの素材。</td><td>制作時に用意し、ゲームから参照する。</td></tr><tr><td><strong>利用者の設定</strong></td><td>表示言語、キー割り当て、画面の設定。</td><td>選んだ設定を保存し、次回も適用する。</td></tr><tr><td><strong>進行状況</strong></td><td>クリアしたステージ、所持アイテム、現在のHP。</td><td>ゲームが保存対象と保存時点を決める。</td></tr></tbody></table><p>すべてのデータを一つのファイルへ保存するか、設定と進行を分けるかは設計で決めます。例えば弾の描画に使うメッシュを保存し直す代わりに、必要なアイテムやステージを識別する<strong>ID</strong>を保存し、読み込み時に対応するアセットを探す構成にできます。<a href="/study/game/asset-loading.html">アセットの読み込みと所有権</a> · <a href="/study/design/case-studies/save-data.html">セーブデータの設計</a></p><h2 id="保存用の値を、ファイルにできる形へ変える" tabindex="-1">保存用の値を、ファイルにできる形へ変える <a class="header-anchor" href="#保存用の値を、ファイルにできる形へ変える" aria-label="Permalink to &quot;保存用の値を、ファイルにできる形へ変える&quot;">​</a></h2><p><strong>シリアライズ</strong>は、データの状態を保存や送信ができる表現へ変換する処理です。<strong>デシリアライズ</strong>は、その表現からデータを組み立てる処理です。JSONのようなテキスト形式も、用途に合わせたバイナリ形式も使えます。データを形式に合わせて変換する処理と、変換したデータをファイルへ書く処理は分けて考えます。<a href="https://learn.microsoft.com/en-us/dotnet/standard/serialization/system-text-json/overview" target="_blank" rel="noreferrer">Microsoftのシリアライズの説明</a> · <a href="/study/os/files-and-paths.html">ファイルとパス</a></p><figure class="study-figure"><img src="'+n+`" alt="実行中の状態から保存用の値を集め、JSONなどへシリアライズしてファイルへ書く。再開時にはファイルを読み、データへ変換して版と値を検証し、確認した内容からゲーム状態を復元する。" width="760" height="460" loading="lazy"><figcaption>保存する値を選ぶ処理、表現を変える処理、ファイル操作、ゲームへの復元を順に追います。<a href="/study/images/game/save-data-and-serialization.svg" target="_blank" rel="noopener noreferrer">セーブと復元の図を拡大</a></figcaption></figure><p>例えば次は、説明用の保存データです。<code>version</code>はこの形式の版、<code>stageId</code>はステージを識別する名前とします。</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;stageId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;forest-01&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;player&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;hp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">70</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;maxHp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;itemIds&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;key-blue&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;potion-small&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>この例では、実行中のオブジェクトそのものやメモリアドレスを記録する代わりに、再開に必要な値を選んでいます。ゲームを再開するときは、ステージを読み、必要なオブジェクトを用意して、HPや所持品を適用します。形式に何が含まれ、どの型を扱えるかは、使うシリアライザーの仕様で確認します。<a href="https://learn.microsoft.com/en-us/dotnet/standard/serialization/system-text-json/overview" target="_blank" rel="noreferrer">MicrosoftのSystem.Text.Jsonの概要</a> · <a href="/study/game/basics/scenes-and-components.html">シーンと実行中の状態</a></p><h2 id="読めたデータを、確かめてから適用する" tabindex="-1">読めたデータを、確かめてから適用する <a class="header-anchor" href="#読めたデータを、確かめてから適用する" aria-label="Permalink to &quot;読めたデータを、確かめてから適用する&quot;">​</a></h2><p>この例の読み込みでは、まず復元候補のデータを作り、次の点を確認してからゲームへ反映します。途中の検証で失敗しても、まだ遊べる現在の状態を半端に書き換えずに済みます。</p><ol><li>ファイルを読み取れ、JSONの構造を解釈できたか。</li><li>対応する<code>version</code>か。必要な項目がそろっているか。</li><li><code>stageId</code>や<code>itemIds</code>が、現在のゲームで使えるIDか。</li><li>HPが0以上かつ最大HP以下など、ゲームの値として使える範囲か。</li></ol><p>JSONとして正しくても、必要な項目や値の意味はゲーム側で確かめます。シリアライザーにも、必須項目や未知の項目を扱う設定があります。形式を読む処理の成功と、ゲームへ適用できることを順に確認します。<a href="https://learn.microsoft.com/en-us/dotnet/standard/serialization/system-text-json/required-properties" target="_blank" rel="noreferrer">Microsoftの必須プロパティ</a> · <a href="https://learn.microsoft.com/en-us/dotnet/standard/serialization/system-text-json/missing-members" target="_blank" rel="noreferrer">未知の項目の扱い</a></p><h2 id="古いセーブに項目を追加するとき" tabindex="-1">古いセーブに項目を追加するとき <a class="header-anchor" href="#古いセーブに項目を追加するとき" aria-label="Permalink to &quot;古いセーブに項目を追加するとき&quot;">​</a></h2><p>ゲームを更新して保存形式を変える場合は、対応する版ごとの読み方を用意します。例えば版1に存在しない新項目へ既定値を補い、版2のデータへ変換してから復元できます。この変換を<strong>マイグレーション</strong>と呼びます。どの項目を省略でき、どんな既定値を使うかも、保存形式の規則として決めます。<a href="/study/design/case-studies/save-data.html">セーブデータの互換性を設計する</a></p><h2 id="保存途中の中断も考える" tabindex="-1">保存途中の中断も考える <a class="header-anchor" href="#保存途中の中断も考える" aria-label="Permalink to &quot;保存途中の中断も考える&quot;">​</a></h2><p>書き込み中にアプリが終了すると、ファイルの内容が途中までになる場合があります。別の一時ファイルへ完成した内容を書き、確認した後に保存先を置き換える方法や、前の保存を残す方法を検討できます。置き換えと障害後の復旧で保証できる範囲は、OSや保存先、フラッシュの方法も含めて確認します。<a href="/study/os/file-write-and-durability.html">Windowsの書き込みと永続化</a></p><p>保存先も、対象プラットフォームの規則に合わせます。例えばUnityの<code>Application.persistentDataPath</code>は、実行間でデータを保持するための場所を表し、実際のパスはプラットフォームによって変わります。<a href="https://docs.unity3d.com/6000.0/Documentation/ScriptReference/Application-persistentDataPath.html" target="_blank" rel="noreferrer">UnityのpersistentDataPath</a></p><p>どのゲーム状態で保存を許可するかは、<a href="/study/game/basics/game-states-and-pause.html">ゲームの状態とポーズ</a>へつながります。</p>`,21)])])}const u=s(r,[["render",o]]);export{g as __pageData,u as default};
